import java.util.*;

class Solution {
  public int[] shortestDistanceAfterQueries(int n, int[][] queries) {
    List<Integer>[] g = new ArrayList[n];
    for (int i = 0; i < n; i++) {
      g[i] = new ArrayList<>();
      if (i + 1 < n) g[i].add(i + 1);
    }
    int[] answer = new int[queries.length];
    for (int qi = 0; qi < queries.length; qi++) {
      g[queries[qi][0]].add(queries[qi][1]);
      answer[qi] = bfs(g, n);
    }
    return answer;
  }

  private int bfs(List<Integer>[] g, int n) {
    int[] d = new int[n];
    Arrays.fill(d, -1);
    d[0] = 0;
    int[] q = new int[n];
    int head = 0, tail = 1;
    q[0] = 0;
    while (head < tail) {
      int u = q[head++];
      for (int v : g[u])
        if (d[v] < 0) {
          d[v] = d[u] + 1;
          q[tail++] = v;
        }
    }
    return d[n - 1];
  }
}
